sys_script.script:
/*
 * Business Rule: Auto Assignment
 * Table: Incident
 * When: before
 * Insert: true
 * Update: true
 *
 * Adjust category values/group sys_ids for your PDI.
 */

(function executeRule(current, previous) {

    if (!current.category) {
        return;
    }

    var groupMap = {
        'hardware': 'Hardware Support',
        'software': 'Software Support',
        'access': 'Access Management'
    };

    var targetGroup = groupMap[current.category.toString().toLowerCase()];

    if (!targetGroup) {
        targetGroup = 'Service Desk';
    }

    var group = new GlideRecord('sys_user_group');
    group.addQuery('name', targetGroup);
    group.setLimit(1);
    group.query();

    if (group.next()) {
        current.assignment_group = group.getUniqueValue();
    }

})(current, previous);

/*
 * Business Rule: Critical Incident Audit
 * Table: Incident
 * When: after
 * Insert: true
 * Update: true
 *
 * Creates an audit note when an incident becomes Critical, and pushes a
 * notification to the external ops webhook via ESPExternalNotifier.
 */

(function executeRule(current, previous) {

    var becameCritical =
        current.impact.toString() === '1' &&
        (!previous || previous.impact.toString() !== '1');

    if (!becameCritical) {
        return;
    }

    gs.info(
        '[Employee Service Portal] Critical incident detected: ' +
        current.getDisplayValue('number')
    );

    var notifier = new ESPExternalNotifier();
    notifier.notifyExternalSystem(current);

})(current, previous);

/*
 * Business Rule: Catalog Request Sync
 * Table: Requested Item (sc_req_item)
 * When: after
 * Update: true
 * Condition: current.approval CHANGES
 *
 * Mirrors the requested item's approval state onto the parent Request so
 * the requester sees a consistent status without opening each item, and
 * kicks off the notifications defined in NOTIFICATION_CATALOG.md.
 */

(function executeRule(current, previous) {

    if (!current.approval.changes()) {
        return;
    }

    var approval = current.approval.toString();
    var request = new GlideRecord('sc_request');

    if (!request.get(current.request)) {
        return;
    }

    if (approval === 'approved') {
        gs.eventQueue('esp.request.approved', current, current.request_item, current.cat_item.getDisplayValue());
    } else if (approval === 'rejected') {
        current.state = 'closed_incomplete';
        current.update();
        gs.eventQueue('esp.request.rejected', current, current.request_item, current.cat_item.getDisplayValue());
    }

})(current, previous);

sys_script_client.script:
/*
 * Client Script: Critical Impact Validation
 * Type: onChange
 * Table: Incident
 * Field: Business Impact
 */

function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) {
        return;
    }

    var justificationField = 'u_business_justification';

    if (newValue === 'critical') {
        g_form.setMandatory(justificationField, true);
        g_form.showFieldMsg(
            justificationField,
            'Business justification is required for Critical impact incidents.',
            'info'
        );
    } else {
        g_form.setMandatory(justificationField, false);
    }
}

/*
 * Client Script: Get Open Incident Count
 * Type: onLoad
 * Table: Incident
 *
 * Demonstrates asynchronous GlideAjax.
 */

function onLoad() {
    var ga = new GlideAjax('ESPIncidentUtils');
    ga.addParam('sysparm_name', 'getOpenIncidentCount');
    ga.getXMLAnswer(function(answer) {
        var count = parseInt(answer, 10) || 0;

        if (count > 0) {
            g_form.addInfoMessage(
                'You currently have ' + count + ' open incident(s).'
            );
        }
    });
}

sys_script_include.script:
/*
 * Script Include: ESPIncidentUtils
 * Client callable: true
 *
 * Demonstrates GlideRecord + GlideAjax.
 */

var ESPIncidentUtils = Class.create();
ESPIncidentUtils.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    getOpenIncidentCount: function() {
        var count = 0;
        var userId = gs.getUserID();

        var gr = new GlideRecord('incident');
        gr.addQuery('caller_id', userId);
        gr.addQuery('active', true);
        gr.query();

        while (gr.next()) {
            count++;
        }

        return count.toString();
    },

    type: 'ESPIncidentUtils'
});

/*
 * Script Include: ESPExternalNotifier
 * Client callable: false
 *
 * Sends a REST callout to an external ops/incident-management webhook
 * whenever an incident in this app becomes Critical, so on-call tooling
 * outside ServiceNow (Slack/Teams channel, PagerDuty, etc.) gets notified
 * without polling the instance.
 *
 * The outbound REST Message record ("ESP Ops Webhook") holds the actual
 * endpoint URL and auth, configured per-environment — nothing here is
 * environment specific.
 */

var ESPExternalNotifier = Class.create();
ESPExternalNotifier.prototype = {
    initialize: function() {},

    REST_MESSAGE_NAME: 'ESP Ops Webhook',
    REST_MESSAGE_METHOD: 'notify_critical',

    notifyExternalSystem: function(incidentGr) {
        if (!incidentGr || !incidentGr.isValidRecord()) {
            return false;
        }

        try {
            var request = new sn_ws.RESTMessageV2(this.REST_MESSAGE_NAME, this.REST_MESSAGE_METHOD);

            var payload = {
                number: incidentGr.getValue('number'),
                short_description: incidentGr.getValue('short_description'),
                assignment_group: incidentGr.getDisplayValue('assignment_group'),
                impact: incidentGr.getValue('impact'),
                sys_id: incidentGr.getUniqueValue(),
                instance_url: gs.getProperty('glide.servlet.uri') + 'incident.do?sys_id=' + incidentGr.getUniqueValue()
            };

            request.setRequestBody(JSON.stringify(payload));
            var response = request.execute();
            var status = response.getStatusCode();

            if (status < 200 || status >= 300) {
                gs.warn('[ESPExternalNotifier] Webhook call for ' + payload.number +
                    ' returned status ' + status);
                return false;
            }

            return true;
        } catch (ex) {
            gs.error('[ESPExternalNotifier] Failed to notify external system: ' + ex.getMessage());
            return false;
        }
    },

    type: 'ESPExternalNotifier'
};

sys_ws_operation.operation_script:
/*
 * Scripted REST Resource: Incident Summary
 * API: ESP Incident Summary API
 * Base path: /api/x_kap_esp/incident_summary
 * Method: GET
 * Required role: x_kap_esp.it_manager
 *
 * Read-only endpoint for external systems (reporting tools, status pages)
 * to pull a lightweight open-incident count by assignment group without
 * needing direct table access.
 */

(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var groups = ['Service Desk', 'Hardware Support', 'Software Support', 'Access Management'];
    var summary = [];

    groups.forEach(function(groupName) {
        var gr = new GlideRecord('incident');
        gr.addQuery('assignment_group.name', groupName);
        gr.addQuery('active', true);
        gr.query();

        summary.push({
            group: groupName,
            open_incidents: gr.getRowCount()
        });
    });

    response.setStatus(200);
    response.setBody({
        generated_on: new GlideDateTime().getDisplayValue(),
        summary: summary
    });

})(request, response);
